code='def is_band_matrix(a):\n    n=len(a)\n    for r in range(n):\n        for c in range(n):\n            if abs(r-c) <= 1:\n                if a[r][c] == 0:\n                    return False\n            elif a[r][c] != 0:\n                return False\n    return True'
